# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">REKOMBİNANT DNA TEKNOLOJİSİ VE GEN KLONLAMA AŞAMALARI</text>\n  <rect x="20" y="45" width="145" height="95" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="92" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. İzolasyon ve Kesim</text>\n  <text x="92" y="85" text-anchor="middle" font-size="10.5" fill="#1e3a8a">İstenen gen (DNA) ve</text>\n  <text x="92" y="101" text-anchor="middle" font-size="10.5" fill="#1e3a8a">bakteri plazmiti aynı</text>\n  <text x="92" y="117" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">restriksiyon enzimiyle</text>\n  <text x="92" y="131" text-anchor="middle" font-size="10" fill="#1e3a8a">kesilir (yapışkan uçlar).</text>\n  <path d="M 167 92 L 188 92" stroke="#2563eb" stroke-width="2.5"/>\n  <rect x="190" y="45" width="145" height="95" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="262" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. Ligasyon (Birleşme)</text>\n  <text x="262" y="85" text-anchor="middle" font-size="10.5" fill="#14532d">Gen ve açık plazmit</text>\n  <text x="262" y="101" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">DNA ligaz enzimiyle</text>\n  <text x="262" y="117" text-anchor="middle" font-size="10.5" fill="#14532d">fosfodiester bağı kurarak</text>\n  <text x="262" y="131" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">rDNA oluşturur.</text>\n  <path d="M 337 92 L 358 92" stroke="#16a34a" stroke-width="2.5"/>\n  <rect x="360" y="45" width="145" height="95" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="432" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. Transformasyon</text>\n  <text x="432" y="85" text-anchor="middle" font-size="10.5" fill="#78350f">Rekombinant plazmit</text>\n  <text x="432" y="101" text-anchor="middle" font-size="10.5" fill="#78350f">(rDNA) konak bakteri</text>\n  <text x="432" y="117" text-anchor="middle" font-size="10.5" fill="#78350f">hücresine (<tspan font-style="italic">E. coli</tspan>)</text>\n  <text x="432" y="131" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">aktarılır.</text>\n  <path d="M 507 92 L 528 92" stroke="#d97706" stroke-width="2.5"/>\n  <rect x="530" y="45" width="150" height="95" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="605" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. Çoğaltım ve Ürün</text>\n  <text x="605" y="85" text-anchor="middle" font-size="10.5" fill="#581c87">Bakteriler bölündükçe</text>\n  <text x="605" y="101" text-anchor="middle" font-size="10.5" fill="#581c87">gen klonlanır; insülin,</text>\n  <text x="605" y="117" text-anchor="middle" font-size="10.5" fill="#581c87">interferon ve büyüme</text>\n  <text x="605" y="131" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">hormonu üretilir.</text>\n  <rect x="20" y="155" width="660" height="88" rx="8" fill="#eff6ff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">MODEL ORGANİZMALARIN TEMEL ÖZELLİKLERİ (12.1.2.3)</text>\n  <text x="35" y="198" font-size="11" fill="#1e3a8a">• Kısa yaşam döngüsüne sahip olma ve laboratuvarda kolay yetiştirilebilme (<tspan font-style="italic">E. coli</tspan>, <tspan font-style="italic">Drosophila melanogaster</tspan>).</text>\n  <text x="35" y="216" font-size="11" fill="#1e3a8a">• Küçük genom büyüklüğü, genom haritasının bilinmesi ve genetik müdahalelere (mutasyon/aktarım) uygunluk.</text>\n  <text x="35" y="234" font-size="11" fill="#1e3a8a">• Örnekler: Bakteri (<tspan font-style="italic">E. coli</tspan>), Bira mayası (<tspan font-style="italic">S. cerevisiae</tspan>), Fare (<tspan font-style="italic">Mus musculus</tspan>), Fare kulağı teresi (<tspan font-style="italic">Arabidopsis thaliana</tspan>).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MODERN BİYOTEKNOLOJİ: KÖK HÜCRE, CRISPR-Cas9 VE BİYOGÜVENLİK</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Kök Hücre Kaynakları</text>\n  <rect x="34" y="82" width="182" height="44" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="125" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Embriyonik Kök Hücre</text>\n  <text x="125" y="116" text-anchor="middle" font-size="10" fill="#7f1d1d">Blastula evresi; tüm hücrelere dönüşür.</text>\n  <rect x="34" y="134" width="182" height="44" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="125" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Göbek Kordonu Kanı</text>\n  <text x="125" y="168" text-anchor="middle" font-size="10" fill="#7f1d1d">Doğumda alınır; bağışıklık uyumu yüksek.</text>\n  <rect x="34" y="186" width="182" height="44" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="125" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Yetişkin Kök Hücre</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" fill="#7f1d1d">Kemik iliği, yağ, deri; dönüşüm sınırlı.</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Genom Düzenleme ve Analiz</text>\n  <text x="257" y="92" font-size="11" font-weight="bold" fill="#1e3a8a">• CRISPR-Cas9 Teknolojisi:</text>\n  <text x="265" y="108" font-size="10.5" fill="#1e3a8a">Rehber RNA ile hedef DNA dizisi</text>\n  <text x="265" y="123" font-size="10.5" fill="#1e3a8a">bulunur, Cas9 enzimiyle kesilerek</text>\n  <text x="265" y="138" font-size="10.5" fill="#1e3a8a">hatalı gen düzeltilir veya susturulur.</text>\n  <text x="257" y="164" font-size="11" font-weight="bold" fill="#1e3a8a">• DNA Parmak İzi ve PCR:</text>\n  <text x="265" y="180" font-size="10.5" fill="#1e3a8a">Tekrarlayan baz dizileri PCR ile</text>\n  <text x="265" y="195" font-size="10.5" fill="#1e3a8a">çoğaltılır; jel elektroforezinde bant</text>\n  <text x="265" y="210" font-size="10.5" fill="#1e3a8a">profilleriyle adli tıp ve babalık</text>\n  <text x="265" y="225" font-size="10.5" fill="#1e3a8a">testlerinde kimlik tespiti yapılır.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">GDO, Transgenik ve Biyoetik</text>\n  <text x="482" y="92" font-size="11" font-weight="bold" fill="#14532d">• Transgenik Canlı (GDO):</text>\n  <text x="490" y="108" font-size="10.5" fill="#14532d">Farklı bir türden gen aktarılmış</text>\n  <text x="490" y="123" font-size="10.5" fill="#14532d">organizma (Örn: A vitamini öncülü</text>\n  <text x="490" y="138" font-size="10.5" fill="#14532d">beta-karoten üreten Altın Pirinç).</text>\n  <text x="482" y="164" font-size="11" font-weight="bold" fill="#14532d">• Biyogüvenlik (Cartagena):</text>\n  <text x="490" y="180" font-size="10.5" fill="#14532d">GDO\'ların biyoçeşitlilik, ekolojik</text>\n  <text x="490" y="195" font-size="10.5" fill="#14532d">denge ve insan sağlığı üzerindeki</text>\n  <text x="490" y="210" font-size="10.5" fill="#14532d">olası risklerini denetleyen yasal</text>\n  <text x="490" y="225" font-size="10.5" fill="#14532d">ve biyoetik kurallar bütünüdür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FOTOSENTEZİN IŞIĞA BAĞIMLI VE IŞIKTAN BAĞIMSIZ EVRELERİ</text>\n  <rect x="25" y="45" width="275" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="162" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">1. Işığa Bağımlı Tepkimeler</text>\n  <text x="162" y="84" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Kloroplastın Tilakoit Zarı / Granum)</text>\n  <text x="38" y="108" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Girenler:</tspan> Işık, H₂O, ADP + Pᵢ, NADP⁺</text>\n  <text x="38" y="128" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Suyun Fotolizi:</tspan> 2H₂O → 4H⁺ + 4e⁻ + O₂</text>\n  <text x="38" y="148" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Fotofosforilasyon:</tspan> ETS ile ATP sentezi</text>\n  <text x="38" y="168" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">NADP⁺ İndirgenmesi:</tspan> NADPH üretimi</text>\n  <rect x="38" y="185" width="248" height="40" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="162" y="203" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Atmosfere verilen O₂\'nin kaynağı</text>\n  <text x="162" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">fotolize uğrayan H₂O molekülleridir!</text>\n  <path d="M 305 110 L 395 110" stroke="#d97706" stroke-width="3"/>\n  <text x="350" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">ATP ve NADPH</text>\n  <path d="M 395 165 L 305 165" stroke="#2563eb" stroke-width="3"/>\n  <text x="350" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">ADP + Pᵢ ve NADP⁺</text>\n  <rect x="400" y="45" width="275" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="537" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Işıktan Bağımsız Tepkimeler</text>\n  <text x="537" y="84" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">(Kloroplastın Stroma Sıvısı - Calvin)</text>\n  <text x="413" y="108" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Girenler:</tspan> CO₂, ATP, NADPH</text>\n  <text x="413" y="128" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Karbon Tutulması:</tspan> Rubisco enzimi ile</text>\n  <text x="413" y="148" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">NADPH Yükseltgenmesi:</tspan> NADP⁺ oluşumu</text>\n  <text x="413" y="168" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Kilit Ürün:</tspan> PGAL (Fosfogliser aldehit)</text>\n  <rect x="413" y="185" width="248" height="40" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="537" y="203" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">PGAL\'den glikoz, amino asit, yağ asidi,</text>\n  <text x="537" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">gliserol ve vitaminler sentezlenir!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
